package org.jkiss.dbeaver.teststudio.core;
import com.google.gson.*;import java.util.*;import org.eclipse.core.runtime.*;import org.jkiss.dbeaver.teststudio.spi.TestReportProvider;
final class ReportRegistry{private static final String EXT="org.jkiss.dbeaver.teststudio.core.reportProvider";private final Map<String,TestReportProvider> providers=new LinkedHashMap<>();ReportRegistry(){register(new JsonReportProvider());register(new JUnitReportProvider());register(new HtmlReportProvider());register(new MarkdownReportProvider());IExtensionRegistry r=Platform.getExtensionRegistry();if(r!=null)for(IConfigurationElement e:r.getConfigurationElementsFor(EXT))try{Object o=e.createExecutableExtension("class");if(o instanceof TestReportProvider p)register(p);}catch(Exception ignored){}}private void register(TestReportProvider p){providers.merge(p.format(),p,(a,b)->a.priority()<=b.priority()?a:b);}JsonObject describe(){JsonArray a=new JsonArray();providers.values().forEach(p->{JsonObject i=new JsonObject();i.addProperty("format",p.format());i.addProperty("extension",p.extension());a.add(i);});JsonObject r=new JsonObject();r.addProperty("count",a.size());r.add("providers",a);return r;}JsonObject generate(RunEvidenceStore store,String project,String runId,String format,JsonObject options,boolean overwrite){TestReportProvider p=providers.get(format);if(p==null)throw new IllegalArgumentException("Unknown report format: "+format);JsonObject run=store.get(project,runId).getAsJsonObject("report");try{return store.writeReport(project,runId,p.format(),p.extension(),p.generate(run,options),overwrite);}catch(Exception e){throw new IllegalStateException("Report generation failed: "+StudioJson.safe(e),e);}}}
